class Solution {
    public int minRectanglesToCoverPoints(int[][] points,int w){
        Arrays.sort(points,(a,b)->Integer.compare(a[0],b[0]));
        int answer=0,index=0;
        while(index<points.length){
            long right=(long)points[index][0]+w;
            answer++;
            while(index<points.length&&points[index][0]<=right)index++;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minRectanglesToCoverPoints(points:Array<IntArray>,w:Int):Int{
        points.sortWith(compareBy<IntArray>{
            it[0]
        });
        var answer=0;
        var index=0;
        while(index<points.size){
            val right=points[index][0].toLong()+w;
            answer++;
            while(index<points.size&&points[index][0].toLong()<=right)index++
        };
        return answer
    }
}

code.cpp:
class Solution {
    public:int minRectanglesToCoverPoints(vector<vector<int>>& points,int w){
        sort(points.begin(),points.end(),[](const auto& a,const auto& b){
            return a[0]<b[0];
        });
        int answer=0,index=0;
        while(index<(int)points.size()){
            long long right=(long long)points[index][0]+w;
            ++answer;
            while(index<(int)points.size()&&points[index][0]<=right)++index;
        }
        return answer;
    }
};
